import { PASSWORD, USERS, expect, test } from "../../fixtures";

test("unknown email is rejected the same way as a wrong password", { tag: "@AUTH-03" }, async ({ request }) => {
  // Act
  const unknown = await request.post("/api/auth/login", {
    data: { email: "nobody@northwind.test", password: PASSWORD },
  });
  const unknownBody = await unknown.text();

  const wrongPassword = await request.post("/api/auth/login", {
    data: { email: USERS.member, password: "wrong-password" },
  });
  const wrongBody = await wrongPassword.text();

  // Assert
  expect(unknown.status(), unknownBody).toBe(401);
  expect(JSON.parse(unknownBody).error.code, unknownBody).toBe("invalid_credentials");
  expect(wrongPassword.status(), wrongBody).toBe(401);
  expect(JSON.parse(wrongBody).error.code, wrongBody).toBe(JSON.parse(unknownBody).error.code);
});
